import { describe, expect, it } from "vitest";
import { LANGUAGES, languageFromLocale } from "@/i18n/languages";
import backend from "./languages.json";

// languages.json is generated by the backend test
// tray::tests::languages_match_shared_fixture from settings::LANGUAGES and
// map_locale_to_tray_language, so the tray and the window agree on languages.
describe("LANGUAGES matches the backend", () => {
  it("lists the same languages in the same order", () => {
    expect(LANGUAGES.map((language) => language.id)).toEqual(backend.languages);
  });

  it.each(Object.entries(backend.localeToLanguage))(
    "maps system locale %j to %s",
    (locale, language) => {
      expect(languageFromLocale(locale)).toBe(language);
    },
  );
});
